type Glyph = Readonly<{ code: string; w: number; h: number }>;
const pool = new Map<string, Glyph>();             // FlyweightFactory
function glyph(code: string, w: number, h: number): Glyph {
  const key = `${code}:${w}:${h}`;
  let fw = pool.get(key);
  if (fw === undefined) {
    fw = Object.freeze({ code, w, h });            // intrinsic, immutable
    pool.set(key, fw);
  }
  return fw;
}
type Cell = { readonly glyph: Glyph; readonly x: number; readonly y: number };
